import{_ as i,C as e,o as a,c as s,a2 as o,b as n,w as t,a as g,E,a3 as A}from"./chunks/framework.BBdhqAg0.js";const d="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"거래 내역 관리","description":"","frontmatter":{},"headers":[],"relativePath":"ledger/manage.md","filePath":"ledger/manage.md","lastUpdated":1793455234000}'),B={name:"ledger/manage.md"};function c(u,l,C,h,p,m){const r=e("Mermaid");return a(),s("div",null,[l[1]||(l[1]=o('<h1 id="거래-내역-관리" tabindex="-1">거래 내역 관리 <a class="header-anchor" href="#거래-내역-관리" aria-label="Permalink to &quot;거래 내역 관리&quot;">​</a></h1><p>프로젝트에서 발생하는 모든 실제 입출금 내역을 기록하고, 이를 회계 계정 및 계약 정보와 연결하여 관리하는 핵심 화면입니다.</p><ul><li><strong>위치</strong>: <code>회계 자금 관리 &gt; 거래 내역 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+d+'" alt="거래 내역 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/manage.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>통장상의 실제 거래 데이터(은행거래내역)를 등록하고, 각 거래가 회계상 어떤 의미(분류 내역)를 갖는지 정의합니다. 하나의 은행 입출금 건을 여러 개의 회계 계정으로 나누어 분개하는 1:N 분할 전표 처리를 지원하며, 분양 대금 수입이나 외주 용역비 등 특정 계정은 실제 분양 계약 정보와 연결하여 수납 장부 및 회계 장부의 정합성을 보장합니다.</p>',6)),(a(),n(A,null,{default:t(()=>[E(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EA%B1%B0%EB%9E%98%20%EC%A0%95%EB%B3%B4%20%EC%9E%85%EB%A0%A5%3Cbr%2F%3E(%EC%9D%BC%EC%9E%90%C2%B7%EA%B3%84%EC%A2%8C%C2%B7%EC%9E%85%EC%B6%9C%EA%B8%88%EC%95%A1)%22%5D%20--%3E%20B%5B%222.%20%ED%9A%8C%EA%B3%84%20%EA%B3%84%EC%A0%95%20%EB%B6%84%ED%95%A0%3Cbr%2F%3E(1%3AN%20%EB%B6%84%EA%B0%9C%C2%B7%EC%A7%80%EC%B6%9C%EC%A6%9D%EB%B9%99)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EA%B3%84%EC%95%BD%20%EC%A0%95%EB%B3%B4%20%EC%97%B0%EB%8F%99%3Cbr%2F%3E(%EB%B6%84%EC%96%91%EC%88%98%EC%9E%85%C2%B7%EB%AF%B8%EC%88%98%EA%B8%88%20%EB%A7%A4%EC%B9%AD)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%B0%A8%EC%95%A1%20%EA%B2%80%EC%A6%9D%20%ED%99%95%EC%9D%B8%3Cbr%2F%3E(%EC%9D%80%ED%96%89%20%EA%B1%B0%EB%9E%98%EC%95%A1%20%3D%3D%20%EB%B6%84%EB%A5%98%EC%95%A1%20%ED%95%A9%EA%B3%84%20%E2%9C%85)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EC%B5%9C%EC%A2%85%20%EC%A0%80%EC%9E%A5%20%EB%B0%8F%20%EC%9E%A5%EB%B6%80%20%EB%B0%98%EC%98%81%3Cbr%2F%3E(%EC%A0%95%EC%82%B0%20%EB%B3%B4%ED%98%B8%20%EB%B0%8F%20%EC%9D%B4%EB%A0%A5%20%EA%B4%80%EB%A6%AC)%22%5D%0A"})]),fallback:t(()=>[...l[0]||(l[0]=[g(" Loading... ",-1)])]),_:1})),l[2]||(l[2]=o('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>다차원 상세 필터링 및 검색</strong>: 조회 기간, 계정과목(자산/부채/수본/수익/비용), 거래 계좌, 계약 정보 등 다양한 조건 검색</li><li><strong>다수 거래 동시 일괄 입력</strong>: 한 번의 등록 작업으로 여러 건의 독립된 입출금 거래를 행 단위로 신속하게 추가</li><li><strong>1:N 분할 전표(Split Transaction) 지원</strong>: 하나의 출금액을 여러 개의 회계 비목(예: 공사비 + 부가세대급금 등)으로 상세 분개</li><li><strong>계약 및 계약자 필수 연동</strong>: 분양 수입, 분담금 환급 등 계약 관련 계정 선택 시 계약자 선택 팝업을 연동하여 데이터 불일치 차단</li><li><strong>스마트 분개 편의 기능</strong>: 출금 시 이체 수수료(500원) 자동 분개 생성, 내부 계좌 간 이동 시 반대편 &#39;대체(입금)&#39; 거래 자동 제안</li><li><strong>스마트 엑셀 템플릿 대량 업로드</strong>: 대용량 거래 및 분할 전표를 사전에 검증하고 안전하게 불러오는 2단계 임포트 시스템</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-목록-제어-및-검색-필터" tabindex="-1">1. 목록 제어 및 검색 필터 <a class="header-anchor" href="#_1-목록-제어-및-검색-필터" aria-label="Permalink to &quot;1. 목록 제어 및 검색 필터&quot;">​</a></h3><p>원하는 거래 내역을 신속하게 찾기 위한 조건 지정 영역입니다.</p><ul><li><strong>검색 조건</strong>: 거래일자 범위, 입출금 구분(전체/입금/출금), 계정 분류 체계, 상세 계정과목, 거래 계좌, 거래처명 및 적요 키워드</li><li><strong>운영비용(전도금) 포함 보기</strong>: 체크 시 사업비 메인 계좌뿐만 아니라 프로젝트 운영비(전도금) 계좌의 지출 내역까지 통합하여 조회합니다.</li></ul><h3 id="_2-입출금-현황-목록" tabindex="-1">2. 입출금 현황 목록 <a class="header-anchor" href="#_2-입출금-현황-목록" aria-label="Permalink to &quot;2. 입출금 현황 목록&quot;">​</a></h3><p>조회된 거래 내역을 표시하며, 각 행은 상단의 **&#39;은행거래내역&#39;**과 하단의 **&#39;분류 내역(회계 분개)&#39;**으로 나누어 표시됩니다.</p><ul><li><strong>은행거래내역 (통장 원장)</strong>: 실제 통장에 찍힌 거래일자, 계좌명, 적요, 입금액/출금액 정보</li><li><strong>분류 내역 (회계 장부)</strong>: 회계상 적용된 계정과목, 거래처, 분류 금액, 지출 증빙 유형(세금계산서, 카드, 계산서, 간이영수증 등)</li><li><strong>금액 일치 검증 표시기</strong>: <ul><li><strong>초록색 체크(✅)</strong>: 은행 거래 금액과 하단 분류 내역 합계가 100% 일치하는 정상 상태</li><li><strong>노란색/붉은색 경고(⚠️)</strong>: 양측 금액에 차액이 발생한 상태로, 차액 금액이 안내되며 추가 분개가 필요함을 알림</li></ul></li></ul><h3 id="_3-거래-등록-및-수정-폼" tabindex="-1">3. 거래 등록 및 수정 폼 <a class="header-anchor" href="#_3-거래-등록-및-수정-폼" aria-label="Permalink to &quot;3. 거래 등록 및 수정 폼&quot;">​</a></h3><p>새로운 입출금 내역을 생성하거나 기존 거래를 상세 수정하는 영역입니다.</p><ul><li><strong>은행 거래 행 추가</strong>: 신규 등록 시 [행 추가] 버튼을 눌러 여러 건의 통장 거래를 순서대로 입력할 수 있습니다.</li><li><strong>이체 수수료 자동 입력 버튼</strong>: 출금 항목 옆의 수수료 아이콘을 클릭하면 설정된 이체 수수료(예: 500원) 분개 행이 자동으로 추가되어 오타와 누락을 방지합니다.</li><li><strong>대체 거래 자동 감지</strong>: 내부 통장 간 이동을 위해 &#39;대체(출금)&#39; 계정을 선택하면, 상대 계좌로 입금되는 &#39;대체(입금)&#39; 전표를 자동으로 추가 생성할지 묻는 스마트 팝업이 작동합니다.</li></ul><h2 id="📊-대량-엑셀-업로드-가이드-bulk-excel-import" tabindex="-1">📊 대량 엑셀 업로드 가이드 (Bulk Excel Import) <a class="header-anchor" href="#📊-대량-엑셀-업로드-가이드-bulk-excel-import" aria-label="Permalink to &quot;📊 대량 엑셀 업로드 가이드 (Bulk Excel Import)&quot;">​</a></h2><p>대량의 외주 용역비 집행, 공사 기성 지급, 다수 계약자의 일괄 수납 내역을 엑셀 템플릿을 통해 안전하게 일괄 등록할 수 있습니다.</p><h3 id="_1-템플릿-다운로드-및-시트-구성" tabindex="-1">1. 템플릿 다운로드 및 시트 구성 <a class="header-anchor" href="#_1-템플릿-다운로드-및-시트-구성" aria-label="Permalink to &quot;1. 템플릿 다운로드 및 시트 구성&quot;">​</a></h3><p>화면 우측 상단의 <strong>[엑셀 템플릿 다운로드]</strong> 버튼을 클릭하면 3개의 시트로 구성된 스마트 엑셀 서식이 다운로드됩니다.</p><ol><li><strong>거래내역 대량입력 (메인 시트)</strong>: 실제 통장 거래 및 회계 분개 데이터를 입력하는 시트입니다.</li><li><strong>작성안내 시트</strong>: 그룹번호 작성 원리, 지출증빙 코드(세금계산서, 카드, 계산서, 현금영수증 등), 필수 주의사항이 안내되어 있습니다.</li><li><strong>참조목록 시트</strong>: 현재 프로젝트에 등록된 <strong>정확한 거래 계좌명</strong>과 <strong>회계 계정과목명</strong>이 나열되어 있어, 오타 없이 복사하여 붙여넣을 수 있습니다.</li></ol><h3 id="_2-그룹번호-1-n-분할-전표-작성-방법" tabindex="-1">2. 그룹번호(1:N 분할 전표) 작성 방법 <a class="header-anchor" href="#_2-그룹번호-1-n-분할-전표-작성-방법" aria-label="Permalink to &quot;2. 그룹번호(1:N 분할 전표) 작성 방법&quot;">​</a></h3><p>하나의 은행 통장 거래를 여러 회계 계정으로 나누어 분개할 때는 **[그룹번호]**를 활용합니다.</p><ul><li><strong>단일 거래 (1:1 분개)</strong>: <ul><li>1행: 그룹번호 <code>1</code>, 거래일자, 계좌, 적요, 출금 100만원 → 계정(공사비), 분류금액 100만원 입력</li></ul></li><li><strong>분할 거래 (1:N 분개)</strong>: <ul><li>1행: 그룹번호 <code>2</code>, 거래일자, 계좌, 적요, 출금 150만원 → 계정A(공사비), 분류금액 100만원 입력</li><li>2행: 그룹번호 <code>2</code>, <strong>은행거래 정보는 빈칸</strong> → 계정B(부가세), 분류금액 50만원 입력</li><li><em>주의: 동일한 그룹번호에 속한 분류금액 합계(100만 + 50만)는 은행 출금액(150만)과 정확히 일치해야 합니다.</em></li></ul></li></ul><h3 id="_3-사전-검증-및-미리보기-bulk-upload-dialog" tabindex="-1">3. 사전 검증 및 미리보기 (Bulk Upload Dialog) <a class="header-anchor" href="#_3-사전-검증-및-미리보기-bulk-upload-dialog" aria-label="Permalink to &quot;3. 사전 검증 및 미리보기 (Bulk Upload Dialog)&quot;">​</a></h3><p>작성한 엑셀 파일을 업로드하면 데이터베이스에 즉시 저장되지 않고 <strong>사전 검증 미리보기 창</strong>이 열립니다.</p><ul><li><strong>행 단위 정밀 검증</strong>: 날짜 형식 오류, 미등록 계정명, 입출금액과 분류금액 불일치 건을 사전에 감지하여 붉은색 경고(✖)로 표시합니다.</li><li><strong>정상 거래만 선별 반영</strong>: 오류가 포함된 거래는 자동으로 제외하고, 정상 검증된 건만 폼에 안전하게 반영할 수 있습니다.</li><li><strong>반영 방식 선택</strong>: <ul><li><code>현재 입력 내용 대체</code>: 기존에 작성 중이던 폼 내용을 비우고 엑셀 데이터로 교체합니다.</li><li><code>현재 입력 내용 뒤에 추가</code>: 기존 작성 중이던 거래 뒤에 이어서 추가합니다.</li></ul></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>2단계 안전 저장 프로세스 (Pre-apply → Final Save)</strong> 엑셀을 업로드하더라도 데이터베이스에 즉시 저장되지 않고 <strong>화면 입력 폼으로 먼저 안전하게 로드</strong>됩니다. 화면에서 최종 검토를 마친 후 상단의 <strong>[저장/생성]</strong> 버튼을 클릭해야 비로소 데이터베이스에 최종 기록되므로 데이터 오염 사고를 원천 방지합니다.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>1회 업로드 권장 상한선</strong> 브라우저 메모리 및 렌더링 안정성을 위해 <strong>1회 업로드 시 은행 거래 50건 / 회계 계정 200행 이하</strong>로 나누어 등록하는 것을 권장합니다.</p></div><h2 id="💡-실무-활용-팁-및-주의-사항" tabindex="-1">💡 실무 활용 팁 및 주의 사항 <a class="header-anchor" href="#💡-실무-활용-팁-및-주의-사항" aria-label="Permalink to &quot;💡 실무 활용 팁 및 주의 사항&quot;">​</a></h2><ul><li><strong>계정별 필수 정보 매칭</strong>: 분양수입, 미수금, 미지급금 등 <strong>계약 정보와 직접 연결되는 계정</strong>을 선택하면 시스템이 자동으로 [계약 정보 선택] 창을 띄웁니다. 이를 통해 수납 관리 메뉴와 회계 관리 메뉴의 데이터가 완벽하게 일치하게 됩니다.</li><li><strong>수정 제한 (정산 마감 보호)</strong>: 최종 정산이 완료된 일자 이전의 거래나, 시스템에 등록된 후 일정 기간(기본 10일)이 경과한 과거 데이터는 임의 수정 및 삭제가 제한됩니다. 수정이 필요할 경우 관리자 권한을 가진 담당자에게 잠금 해제를 요청해야 합니다.</li><li><strong>지출 증빙 코드 관리</strong>: 세금계산서, 계산서, 신용카드 영수증 등 적격 증빙 유형을 빠짐없이 선택해 두면 부가세 신고 및 회계 결산 감사 시 증빙 누락을 쉽게 추적할 수 있습니다.</li></ul>',27))])}const k=i(B,[["render",c]]);export{b as __pageData,k as default};
